(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ro"] = {"ui":{"skip":"Sari la conținut","back":"← Înapoi la AI-gile","lang.button":"Limba: {name}","lang.dialog":"Alege o limbă","lang.search":"Caută limbi","lang.none":"Nicio limbă nu se potrivește","lang.notYet":"{name} nu e tradusă încă","theme.aria":"Schimbă tema: luminoasă, întunecată sau neagră","theme.toLight":"Treci la tema luminoasă","theme.toDark":"Treci la tema întunecată","theme.toBlack":"Treci la tema neagră (negru adevărat, blândă cu ecranele OLED)","words.underline":"Subliniază aceste cuvinte în pagină","words.underlineHelp":"Treci cu mouse-ul peste un cuvânt punctat sau atinge-l ca să vezi ce înseamnă.","index.title":"AI-gile: echipa ta de dezvoltare AI, pe o singură tablă","index.description":"AI-gile este o tablă kanban pentru echipe de programare cu AI. Ele lucrează cât dormi; tu primești o grămadă mică de lucruri de decis, de testat și de acceptat.","hero.logoAlt":"Pictograma tablei AI-gile","hero.h1.html":"Echipa ta de dezvoltare AI, pe o singură&nbsp;tablă.","hero.alpha":"🐣 Pre-alfa închis","hero.alphaTitle":"Început și neterminat: mulțumim că îl încerci!","hero.lede":"Ele construiesc cât dormi. Tu te trezești cu o grămadă mică: câteva întrebări, câteva lucruri de testat, un diamant mov sau două. Un clic, accepți, și te întorci la cafea.","dl.windows":"Aplicație pentru Windows","dl.browser":"Rulează-l în browser","dl.messenger":"📱 Messenger pentru telefonul tău","dl.soon":"În curând","dl.notify":"🔔 Anunță-mă când se deschide","dl.notifySmall":"Alfa sau beta","hero.secondary":"Agile, dar echipa nu are nevoie de cafeaua de la stand-up. (Fac stand-up oricum.)","pitch.h2":"AI-gile în câte cuvinte vrei","pitch.lede":"Alege o lungime, de la un cuvânt la 144. Fiecare lungime e o descriere aparte, scrisă pentru mărimea ei. Trage de cursor sau folosește săgețile.","pitch.rangeLabel":"Lungimea în cuvinte","pitch.dice":"🎲 altă versiune","pitch.words.one":"{n} cuvânt","pitch.words.other":"{n} de cuvinte","pitch.letters.one":"{n} literă","pitch.letters.other":"{n} de litere","pitch.chars.one":"{n} caracter","pitch.chars.other":"{n} de caractere","count.line.html.one":"{n} card pe tablă chiar acum","count.line.html.other":"{n} de carduri pe tablă chiar acum","people.humans.html.one":"👥 {n} om","people.humans.html.other":"👥 {n} de oameni","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} de agenți","people.working.html.one":"⚡ {n} la treabă chiar acum","people.working.html.other":"⚡ {n} la treabă chiar acum","pre.title":"AI-gile: aici se construiește ceva","pre.description":"Aici se construiește ceva: o tablă pe care echipe AI construiesc ce le ceri și te învață pe parcurs. Deocamdată pre-alfa închis, cu prieteni.","pre.h1":"Aici se construiește ceva. 🤫","pre.line":"O tablă pe care echipe AI construiesc ce le ceri și te învață pe parcurs. Deocamdată pre-alfa închis, cu prieteni.","pre.btn":"🔔 Anunță-mă când se deschide","pre.peek":"În spatele sticlei: tabla adevărată, în direct. Fiecare card e o bară colorată.","pre.peekFake":"În spatele sticlei: așa arată o tablă la lucru.","features.aria":"Ce face","f.pile.h":"O singură grămadă pentru tine","f.pile.html":"<b>Pentru tine</b> adună tot ce te așteaptă, din toate proiectele: întrebări, lucruri de testat, sarcini pe care le poate face doar un om. Coada ta spune ce urmează și cât durează.","f.sleep.h":"Echipe care lucrează cât dormi","f.sleep.p":"Fiecare proiect are un lider și o echipă de agenți AI. Lași un comentariu la un card, echipa se trezește, face treaba și ți-l dă înapoi cu pași pe care îi poate urma și un om obosit.","f.tester.h":"Un tester AI verifică primul","f.tester.p":"Înainte să ajungă la tine, un tester urmează pașii într-o copie a aplicației și arată ce a văzut, cu o captură de ecran. Răsfoiești rapid ce a trecut și accepți dintr-un clic.","f.proof.h":"Dovezi, nu promisiuni","f.proof.p":"Fiecare predare arată ce s-a schimbat: fișierele, diferențele, capturile de ecran. Nu mai deschizi fiecare aplicație ca să afli dacă e gata.","f.chat.h":"Vorbește cu liderii tăi","f.chat.p":"O bară în stil Discord: o pictogramă pentru fiecare proiect, diamante mov pentru ce are nevoie de tine. Trimite unui lider o idee; o transformă în carduri și într-un plan, cu un buton ✅ Go.","f.tidy.h":"Se ține singură în ordine","f.tidy.p":"Cardurile înrudite se unesc într-unul, titlurile încurcate se repară, iar o verificare a tokenilor ține codul suplu. Mai puține lucruri între care să sari, mai puține de gândit.","f.private.h":"A ta, pe calculatorul tău","f.private.li1":"Tabla rulează pe calculatorul tău și răspunde numai ție.","f.private.li2":"Mesajele private dintre oameni sunt criptate de la un capăt la altul.","f.private.li3":"Fără conturi, fără urmăritoare, fără cookie-uri.","f.lang.h":"În limba ta","f.lang.p":"Peste 120 de limbi, de la neerlandeză, galeză și japoneză până la limba piraților, a lui Yoda și klingoniană, cu o trecere rapidă înapoi la engleză pentru termenii de specialitate.","f.service.h":"De la o idee la un serviciu adevărat","f.service.p":"Ai construit cu AI ceva ce oamenii folosesc acum? Marchează-l ca serviciu și panoul te ajută să-l rulezi bine: verificări de disponibilitate, o pagină de status publică, incidente cu o analiză scrisă, modificări care au nevoie de un Go, backupuri verificate zilnic. Ajutorul te învață fiecare pas pe drum.","msgr.h2":"AI-gile Messenger: echipa ta în buzunar","msgr.p1":"Vorbește cu echipa ta AI fără să deschizi board-ul. Scrie-le pe chat liderilor de proiect și prietenilor, vezi pașii de test ai unui card și răspunde-le, totul de pe telefon.","msgr.p2":"Ca să-l asociezi, scanează un cod QR de pe board-ul tău. Prima dată? Un chat demo prietenos îți arată tot.","msgr.when":"Întâi pe Android, apoi o versiune web pentru telefoane și iPhone.","msgr.who":"Liderul proiectului tău","msgr.b1":"Remedierea pentru modul întunecat e gata. Vrei pașii de test?","msgr.b2":"Da, te rog!","msgr.b3":"1. Deschide Setări. 2. Alege Întunecat. Arată bine?","tl.aria":"Cronologie de la prima discuție până la foaia de parcurs","tl.h2":"De la prima discuție la ce urmează","tl.lede":"Date și ore reale, în fusul tău orar. După azi e planul, fără date promise.","tl.today":"Azi","tl.planned":"planificat","tl.doing":"în lucru","tl.cards.one":"{n} card","tl.cards.other":"{n} de carduri","join.h2":"Vino și tu","join.lede":"AI-gile e construit de un ciudat bărbos cu AuDHD și câteva lupte cu sănătatea mintală, și de o mulțime de agenți răbdători. Deocamdată e privat, într-un alfa închis, cu prieteni. Vrei să-l încerci când se deschide?","join.btn":"Spune-mi că ești interesat","join.small":"Îți scriem pe e-mail, nimic altceva","footer.tag":"AI-gile. Fără urmăritoare, fără cookie-uri, fără cafea de stand-up.","footer.licence":"Licență pentru firme","footer.status":"Stare","footer.privacy":"Ce păstrăm","footer.thanks":"Apeluri mulțumită ChilledChat","form.sending":"Se trimite…","form.failed":"N-a mers: mai încearcă mai târziu.","form.offline":"Nu am ajuns la AI-gile: mai încearcă mai târziu.","form.keep":"Folosim asta doar ca să-ți răspundem, apoi o ștergem. Fără urmăritoare, fără cookie-uri.","form.keepLink":"Ce păstrăm","interest.title":"AI-gile: anunță-mă când se deschide alfa","interest.description":"Lasă-ți e-mailul ca să afli când se deschide alfa sau beta închisă a AI-gile.","interest.h1":"🔔 Anunță-mă când se deschide","interest.lede":"AI-gile e în pre-alfa închis. Lasă-ți e-mailul și îți scriem o singură dată, când e loc și pentru tine.","interest.email":"E-mailul tău","interest.which":"Ce test?","interest.alpha":"Alfa închis: timpuriu, aspru, cu multe schimbări","interest.beta":"Beta: mai stabil, mai târziu","interest.both":"Oricare, care vine mai întâi","interest.submit":"Pune-mă pe listă","interest.thanks":"Mulțumim! Ești pe listă.","licence.title":"AI-gile: licență pentru firme","licence.description":"Folosești AI-gile în firma ta? Cere o licență gratuită pentru firme.","licence.h1":"📜 Licență pentru firme","licence.lede":"Folosești AI-gile la serviciu? Spune-ne cine ești și ce faci. Dacă face puțin bine, licența e gratuită.","licence.company":"Firma","licence.website":"Site web","licence.what":"Ce faci","licence.how":"Cum ajută lumea","licence.email":"E-mail","licence.submit":"Trimite cererea","licence.thanks":"Mulțumim! Îți răspundem pe e-mail.","status.title":"Starea AI-gile","status.h1":"Starea AI-gile","status.quiet":"Totul e liniștit","status.intro":"Funcționează AI-gile chiar acum? Pagina asta verifică site-ul, partajarea tablelor, apelurile și descărcarea la fiecare 5 minute.","status.up":"Funcționează (a răspuns în {ms} ms)","status.slow":"N-a răspuns la ultima verificare, reîncerc","status.down":"Nu funcționează: n-a răspuns la ultimele două verificări","status.svc.web":"Site","status.svc.web.offers":"Site-ul ăsta: ce e AI-gile și formularul de interes","status.svc.boards":"Partajarea tablelor","status.svc.boards.offers":"Table publice, mesaje între prieteni și invitații","status.svc.calls":"Apeluri","status.svc.calls.offers":"Voce, video și partajarea ecranului în AI-gile","status.svc.download":"Descărcare","status.svc.download.offers":"Programul de instalare pentru Windows și linkurile de invitație","status.checking":"Se verifică…","status.offline":"Nu pot contacta serviciul de stare acum (reîncerc)","status.updated":"actualizat {ago}","status.justNow":"chiar acum","status.min":"acum {n} min","status.hours":"acum {n} h","status.days":"acum {n} z","privacy.title":"AI-gile: ce păstrăm","privacy.h1":"Ce păstrăm","privacy.lede":"Pe scurt: doar ce ne trimiți tu, și nu pentru mult timp.","privacy.only":"Doar ce ne trimiți: ce scrii într-un formular, cum ar fi e-mailul tău. Nimic altceva despre tine.","privacy.sealed":"E sigilat, ca serverul nostru să nu-l poată citi: în browserul tău, înainte să plece (într-un browser mai vechi, în clipa în care ajunge). Doar tabla noastră îl poate deschide.","privacy.server":"E șters de pe server imediat ce ajunge pe tabla noastră. Orice a rămas acolo după 30 de zile e șters oricum.","privacy.board":"Îl păstrăm pe tabla noastră doar până îți răspundem, apoi îl ștergem și de acolo.","privacy.none":"Fără urmăritoare, fără cookie-uri, fără statistici.","privacy.local":"Limba ta și alegerea temei luminoase sau întunecate rămân în browserul tău. Nu ne sunt trimise niciodată.","privacy.ask":"Vrei să dispară mai devreme? Răspunde la e-mailul nostru și spune-ne.","live.h2":"Privește-l cum se construiește, în direct","live.caption":"Fiecare card este ascuns: vezi forma muncii, nu cuvintele.","live.watching.one":"în direct: {n} privește","live.watching.other":"în direct: {n} privesc","live.last.now":"Ultimul card a fost mutat chiar acum","live.last.min.one":"Ultimul card a fost mutat acum {n} min","live.last.min.other":"Ultimul card a fost mutat acum {n} min","live.last.hour.one":"Ultimul card a fost mutat acum {n} oră","live.last.hour.other":"Ultimul card a fost mutat acum {n} ore","live.last.day.one":"Ultimul card a fost mutat acum {n} zi","live.last.day.other":"Ultimul card a fost mutat acum {n} zile","live.offline":"Tabloul live ia o mică pauză. Revino în curând.","live.cols":"Backlog|De făcut|În lucru|Echipa verifică|Așteaptă testul tău|Pentru echipă|Gata","pitch.words.few":"{n} cuvinte","pitch.letters.few":"{n} litere","pitch.chars.few":"{n} caractere","count.line.html.few":"{n} carduri pe tablă chiar acum","tl.cards.few":"{n} carduri"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboți.","Delegat."]},{"n":2,"texts":["Kanban robotic.","Agenți, organizați.","Idei, construite."]},{"n":3,"texts":["Kanban pentru roboți.","Ideile devin funcții.","Kanban gratuit pentru agenți."]},{"n":5,"texts":["O tablă kanban condusă de agenți.","Tu scrii carduri. Agenții construiesc.","Gratuit, local, testat, puțin caraghios."]},{"n":8,"texts":["O tablă kanban gratuită unde lucrează agenți AI.","Scrii o idee. Agenții o construiesc. Tu accepți.","Agile pentru un om și mulți roboți răbdători."]},{"n":13,"texts":["O tablă kanban pe calculatorul tău, unde agenți AI preiau cardurile.","Scrii o idee. O echipă de agenți o construiește. Un tester o verifică.","Gratuit, fără conturi, fără urmăritoare: o tablă, niște roboți și tu la comandă."]},{"n":21,"texts":["AI-gile este o tablă kanban pentru lucrul cu agenți AI de programare. Ei preiau cardurile; tu le testezi și le accepți.","Fiecare proiect primește un lider și o echipă de agenți AI. Lași un comentariu la orice card și echipa se pune pe treabă.","O listă personală de sarcini, gratuită, care rulează pe calculatorul tău. Muncitorii sunt roboți. Cel care spune da ești tu."]},{"n":34,"texts":["Pui ideile pe o tablă. O echipă de agenți AI le face funcții care merg, le testează și ți le dă înapoi cu pași de încercat. Nimic nu e gata până nu spui tu că e gata.","AI-gile este o tablă kanban făcută în casă, pe care Rich a construit-o cu mult ajutor de la agenții pe care acum îi coordonează. E gratuită, rulează pe calculatorul tău și se dă prietenilor, nu se vinde.","Imaginează-ți o tablă kanban obișnuită, cu coloane de la Backlog până la Gata, doar că cardurile sunt preluate de agenți AI. Ei raportează cum merge, întreabă când se blochează și așteaptă mereu încuviințarea ta."]},{"n":55,"texts":["AI-gile este o tablă kanban în care echipa e făcută din agenți AI. Fiecare proiect are un lider care planifică munca și ajutoare care o construiesc. Când o funcție e gata, un tester AI o încearcă și face o captură de ecran, apoi ajunge în grămada ta. O accepți sau lași un comentariu și o refac.","A început ca felul în care un singur om ținea evidența multor sesiuni de programare cu AI deodată și a crescut într-o tablă adevărată. Rulează pe calculatorul tău, nu cere cont și n-are urmăritoare. E gratuită pentru prieteni și pentru oricine e curios. E și neterminată, așa că așteaptă-te la colțuri aspre și la câte o surpriză.","Iată varianta cinstită. Ideile tot tu trebuie să le ai, iar rezultatele tot tu trebuie să le verifici. Ce face AI-gile este tot ce e între ele: ține cardurile în ordine, trezește agentul potrivit când comentezi, arată exact ce s-a schimbat și strânge totul într-o singură grămadă scurtă pentru tine."]},{"n":89,"texts":["AI-gile este o tablă kanban gratuită pe care o rulezi pe propriul calculator. În loc de oameni, fiecare proiect are o echipă de agenți AI: un lider care transformă ideile tale în carduri și într-un plan, și ajutoare care iau cardurile în ordinea priorității. Când ceva e construit, un tester AI urmează pașii de test și îți arată ce a văzut. Apoi așteaptă într-o singură grămadă numită Pentru tine. O accepți sau lași un comentariu și echipa mai încearcă o dată. Nimic nu ajunge vreodată la Gata fără tine.","Câteva lucruri la care poate nu te aștepți. O veghe de noapte ține coloana De făcut plină cât dormi, alegând carduri care nu cer niciun răspuns de la tine. Un contor de tokeni arată cât au folosit agenții azi și săptămâna asta, iar Modul fără tokeni le spune să nu mai cheltuiască. Poți scrie prietenilor, iar mesajele private sunt criptate de la un capăt la altul. Tabla vorbește vreo 120 de limbi, printre ele neerlandeza, flamanda, limba piraților și klingoniana. Nimic din toate astea nu costă un ban și nimeni nu încearcă să ți le vândă.","AI-gile este un proiect mic, personal, nu o companie. Rich voia să țină sub ochi mai multe proiecte de programare cu AI fără să deschidă fiecare aplicație, așa că el și agenții au făcut o tablă pentru asta, apoi au folosit tabla ca să construiască restul. E în pre-alfa închis, ceea ce înseamnă că merge, mai mult sau mai puțin, pentru o mână de prieteni. Nu există pagină de prețuri, buletin informativ sau plan de creștere. Dacă ți se pare util, poți cere să-l încerci când se deschide puțin mai mult."]},{"n":144,"texts":["AI-gile este o tablă kanban pentru un om și o mulțime de agenți AI. Rulează pe propriul tău calculator și este complet gratuită. Adaugi proiecte, iar fiecare proiect primește un lider și o echipă mică. Vorbești cu liderul, cam ca pe Discord, și îi descrii o idee; el o transformă în carduri și într-un plan, apoi așteaptă să apeși Go. Echipa parcurge cardurile în ordinea priorității, folosind o linie de comandă simplă, făcută pentru modelele de limbaj. Înainte să-ți revină ceva, un tester AI urmează pașii într-o copie a aplicației și atașează o captură de ecran. Munca terminată ajunge în grămada ta, cu fișierele schimbate și diferențele. O accepți sau lași un comentariu, iar echipa se trezește și mai încearcă. Doar tu poți muta un card la Gata.","O zi cu AI-gile, în mare. Seara lași câteva comentarii: butonul ăsta e într-un loc nepotrivit, lista aceea ar trebui sortată, am putea avea o temă întunecată. Te duci la culcare. Agenții citesc comentariile, fac schimbările, le testează și ți le dau înapoi. Dacă De făcut rămâne gol, veghea de noapte îl umple din backlog cu carduri care nu cer niciun răspuns de la tine. Dimineața e o singură grămadă scurtă: două întrebări și câteva lucruri de încercat, fiecare cu pași pe care îi poate urma un om somnoros și cu o captură de ecran în care merge. Dai clic prin ele, accepți ce e bun și trimiți înapoi restul. Un contor de tokeni arată cât s-a folosit, iar Modul fără tokeni e pentru săptămânile slabe. Apoi iei micul dejun, la care agenții încă nu pot ajuta.","Mai întâi, ce nu este AI-gile. Nu e un start-up, nu e de vânzare și nimeni nu-ți adună datele. E o tablă gratuită care rulează pe calculatorul tău, fără conturi, fără urmăritoare și fără cookie-uri. Ce este: un singur loc ordonat unde vezi toate proiectele de programare cu AI deodată, cu o echipă de agenți care fac cardurile și tu care iei deciziile. Unește cardurile înrudite, repară titlurile încurcate și urmărește cât de suplu rămâne codul. Vorbește vreo 120 de limbi, de la neerlandeză și flamandă până la limba piraților și klingoniană. Prietenii își pot scrie unii altora, în privat și criptat. A fost construit de Rich și de o mulțime de agenți răbdători, mai ales folosindu-se pe el însuși. E în pre-alfa închis, deci pe alocuri e aspru. Dacă ți se pare distractiv, cere frumos și poate intri mai devreme."]}],"quips":{"1":"Un cuvânt. Îndrăzneț. Poate prea îndrăzneț.","3":"Trei cuvinte. Deja mai cinstit decât majoritatea paginilor de produs.","8":"Opt cuvinte. Tot mai scurt decât un stand-up.","21":"Apropo, lungimile sunt puncte de poveste. Bineînțeles că sunt.","55":"Cincizeci și cinci de cuvinte. Două carduri s-au terminat cât ai citit.","144":"Asta e cea lungă. Nu există 233. Agenții s-au culcat."}},"timeline":{"first-idea.name":"Prima idee","first-idea.line":"Prima discuție, înainte să existe vreun rând de cod.","first-board.name":"Prima tablă","first-board.line":"O tablă care își urmărește propria construcție: carduri, coloane, tragere și plasare, proiecte.","team-roles.name":"Echipă și roluri","team-roles.line":"Profiluri de agenți, șabloane de echipă, spații și cine ce face.","install.name":"Instalare și versiuni","install.line":"Un zip pe care îl poate instala un prieten, actualizări automate, canale și revenire la versiunea veche.","usage-saver.name":"Economie de consum","usage-saver.line":"Măsori cât costă rulările, ții codul suplu, îți economisești limita.","friends.name":"Prieteni și partajare","friends.line":"Mesaje private, un releu criptat, invitații, roluri și proiecte partajate.","languages.name":"Limbi","languages.line":"Fiecare text din ecrane într-un fișier de limbă, cu neerlandeza și flamanda prima.","ai-tester.name":"Tester AI","ai-tester.line":"Un tester verifică fiecare predare mai întâi și arată ce a văzut.","website.name":"Site-ul","website.line":"aigile.lol, pagina de prezentare și această cronologie.","streaming.name":"Chat și streaming","streaming.line":"Discord, Twitch, OBS, modul de streamer, GIF-uri și emoji.","no-ai.name":"Ediția fără AI","no-ai.line":"O tablă pentru cei care programează fără AI, și table publice.","night-watch.name":"Veghea de noapte","night-watch.line":"Un paznic și un Scrum Master țin echipele la treabă cât dormi.","p-more.name":"Tot restul","p-more.line":"Idei mai mici care își așteaptă rândul.","p-android.name":"Telefon și Android","p-android.line":"Ajungi la tablă de pe telefon, apoi printr-o aplicație Android nativă.","p-release.name":"Alfa și mai departe","p-release.line":"Alfa închis, site-ul live, apoi beta.","p-languages.name":"Mai multe limbi","p-languages.line":"130 de limbi și un mod de imersiune pentru cei care învață.","p-engines.name":"Mai multe motoare AI","p-engines.line":"Alege Claude, Codex, Gemini, Copilot sau Cursor pentru fiecare agent.","p-pro.name":"Practică profesionistă","p-pro.line":"Etichete de risc, porți de îmbinare, carduri de incident și balustrade de siguranță.","p-self.name":"Grijă de tine","p-self.line":"Mod obosit, mementouri de îngrijire de sine și 4:20.","p-servers.name":"Servere și scară","p-servers.line":"Setări globale de server, roluri și planificare pentru creștere.","p-livestream.name":"Extra pentru streaming","p-livestream.line":"Chat Twitch, emoji proprii și o vedere publică live."},"words":{"button":"📖 Termeni de specialitate","h":"📖 Cuvinte explicate","intro":"Cuvintele pe care le întâlnești în AI-gile, pe înțelesul tuturor: cum construiești, cum schimbi în siguranță, cum ții totul funcțional pentru cei care îl folosesc și cum lucrezi în echipă cu AI.","search":"Caută un cuvânt…","none":"Niciun cuvânt nu se potrivește.","close":"Închide","count":{"one":"{count} cuvânt","other":"Cuvinte: {count}"},"groups":[{"id":"build","name":"🛠️ Construirea"},{"id":"change","name":"🔀 Modificări în siguranță"},{"id":"run","name":"🛎️ Rularea unui serviciu"},{"id":"team","name":"🤝 Lucrul în echipă (și cu AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Dosarul proiectului cu cod și întregul istoric de commit-uri, de obicei ținut și pe GitHub.","also":["repository","repo-ul","repo-uri"]},{"id":"branch","g":"build","word":"Branch","text":"O linie de lucru separată în cod, ca să poți face modificări fără să atingi versiunea principală.","also":["branch-uri","branch-ul","branch-urile"]},{"id":"commit","g":"build","word":"Commit","text":"Un instantaneu salvat al codului, cu o scurtă notă despre ce s-a schimbat. Poți reveni oricând la el.","also":["commit-uri","commit-ul","commit-urile"]},{"id":"push","g":"build","word":"Push","text":"Trimiterea instantaneelor salvate (commit-uri) de pe acest calculator pe GitHub, ca să fie păstrate în siguranță și partajate."},{"id":"merge","g":"build","word":"Merge","text":"Reunirea modificărilor unui branch în versiunea principală."},{"id":"pr","g":"build","word":"Pull request","text":"Cerere ca modificările unui branch să fie verificate și unite în versiunea principală.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Curățarea codului fără a-i schimba funcția: fișiere mai mici, nume mai clare, mai puține repetiții."},{"id":"bug","g":"build","word":"Bug","text":"Ceva care nu funcționează așa cum ar trebui.","also":["bug-uri","bug-ul","bug-urile","bug-urilor"]},{"id":"test","g":"build","word":"Test","text":"Încercarea unei bucăți de muncă terminate ca să verifici că face ce s-a cerut, înainte s-o accepți.","also":["teste","testul","testului","testare","testat","testezi","testarea"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Prescurtare de la quality assurance, adică asigurarea calității: verificările automate care rulează înainte ca ceva să meargă live. Când QA e roșu, ceva a picat și nu se poate lansa până nu e reparat.","also":["asigurarea calității","verificări de calitate"]},{"id":"deploy","g":"change","word":"Deploy","text":"Publicarea unei versiuni noi live, de exemplu pe un server unde o folosesc oamenii."},{"id":"release","g":"change","word":"Lansare","text":"Un pachet de muncă terminată, cu nume, care merge live deodată, cu note scurte despre ce s-a schimbat. 🚀 Lansări scrie notele din cardurile terminate.","also":["lansări","release","versiune"]},{"id":"rollback","g":"change","word":"Rollback","text":"Întoarcerea la ultima versiune care funcționa, când una nouă face probleme. În AI-gile asta devine o listă de verificare cu pașii de anulare scriși pe fiecare modificare.","also":["revenire","revenire la versiunea anterioară","anulare"]},{"id":"live","g":"change","word":"Live","text":"Versiunea reală pe care o folosesc oamenii, spre deosebire de o copie pentru încercări. Programatorii îi mai spun producție.","also":["producție","în producție"],"noTip":1},{"id":"change","g":"change","word":"Modificare","text":"O schimbare planificată la ceva pe care se bazează oamenii, scrisă dinainte: ce, de ce, riscul, când și cum o anulezi. Începe una cu 🔀 Propune o modificare.","also":["modificări","cerere de modificare","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risc","text":"Ceva ce ar putea merge prost, notat după cât de probabil e și cât de grav ar fi. ⚠️ Riscuri le ține într-o singură listă, cu scorul cel mai mare primul, fiecare cu o dată la care te mai uiți o dată.","also":["riscuri","registrul riscurilor"]},{"id":"chgwin","g":"change","word":"Fereastră de modificări","text":"Momentele în care modificările pot merge live, de exemplu o seară liniștită de marți. În afara unei ferestre, un card de modificare nu poate fi terminat, decât dacă e o urgență.","also":["ferestre de modificări","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Un vot rapid chiar înainte ca o modificare să meargă live: fiecare persoană care trebuie să aprobe spune Go sau No go. Merge mai departe doar când toți sunt de acord.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Aprobare","text":"Așteptarea unui da înainte să înceapă munca. Un card propus de un prieten, sau o modificare, așteaptă în ✅ Aprobări până îl aprobi sau îl respingi.","also":["aprobări"]},{"id":"quiettime","g":"change","word":"Perioadă de liniște","text":"O bucată de timp, ca un stream, un demo sau noaptea, în care nimic nu merge live. Echipele lucrează și testează în continuare, dar lansarea așteaptă până se termină. În alte locuri se numește înghețarea modificărilor.","also":["perioade de liniște","înghețarea modificărilor","change freeze"]},{"id":"service","g":"run","word":"Serviciu","text":"Ceva construit de tine pe care se bazează oamenii, ca un site sau o aplicație, îngrijit ca să funcționeze în continuare. Bifează „Proiectul ăsta e un serviciu” și spune ce oferă, cine îl folosește și cine e de gardă.","also":["servicii"]},{"id":"uptime","g":"run","word":"Verificare de disponibilitate","text":"O verificare automată, la câteva minute, că serviciul tău încă răspunde. Dacă pică de mai multe ori la rând, AI-gile deschide singur un card de incident.","also":["uptime","disponibilitate","uptime check"]},{"id":"statuspage","g":"run","word":"Pagină de status","text":"O pagină publică ce arată dacă un serviciu funcționează (verde, portocaliu sau roșu), cu ultima actualizare, ca cei care îl folosesc să poată verifica în loc să întrebe.","also":["pagini de status","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Locul unde ajung întrebările și semnalările de la oamenii care îți folosesc serviciul. AI-gile pune fiecare la cereri, incidente sau idei și îți spune când seamănă cu ceva deja semnalat.","also":["service desk-uri","birou","birou de asistență","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Cerere de serviciu","text":"Cineva cere ceva obișnuit, de exemplu un cont nou sau puțin ajutor, în loc să semnaleze că s-a stricat ceva. Își așteaptă rândul; un incident trece primul.","also":["cereri de serviciu","cerere"]},{"id":"incident","g":"run","word":"Incident","text":"Ceva ce e stricat chiar acum pentru cei care îl folosesc, de exemplu site-ul e căzut. Un card de 🔥 incident sare peste rând: repunerea în funcțiune vine prima.","also":["incidente","pană","căzut"]},{"id":"major","g":"run","word":"Incident major","text":"Un incident mare: mulți oameni afectați, sau bani ori date în pericol. Un singur buton pune toate echipele pe el (roiul), îl trezește pe cel de gardă și cere o actualizare de status la fiecare 30 de minute.","also":["incidente majore","major incident"]},{"id":"oncall","g":"run","word":"De gardă","text":"Să fii cel care răspunde când se strică ceva, chiar și noaptea. Fiecare serviciu are un membru al echipei de gardă, care e trezit primul la incidentele lui.","also":["gardă","on call","on-call"]},{"id":"replyby","g":"run","word":"Termen de răspuns","text":"Cât poate aștepta un card un prim răspuns, de exemplu o oră pentru un incident. După aceea primește un ceas roșu, ca nimic să nu fie uitat pe tăcute. Se mai numește timp de răspuns țintă.","also":["termene de răspuns","ore de răspuns","timp de răspuns țintă"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"O privire scurtă înapoi după un incident: ce s-a întâmplat, ce a ajutat și ce trebuie schimbat, fără să dai vina pe cineva. Un incident nu poate fi închis fără el.","also":["post-mortemuri","postmortem","analiză după incident"]},{"id":"problem","g":"run","word":"Problemă","text":"Cauza ascunsă din spatele unuia sau mai multor incidente. Un card de 🧩 problemă adună incidentele care tot revin, ca să fie găsită cauza și reparată definitiv.","also":["probleme"],"noTip":1},{"id":"rootcause","g":"run","word":"Cauza principală","text":"Motivul real pentru care s-a stricat ceva, nu doar ce ai văzut mergând prost. Repară cauza principală și incidentul nu mai revine.","also":["cauze principale","cauza rădăcină","root cause"]},{"id":"workaround","g":"run","word":"Soluție provizorie","text":"Un mod de a ține lucrurile funcționale până e gata reparația adevărată, de exemplu repornirea a ceva când se blochează. E scrisă pe cardul problemei, ca nimeni să nu trebuiască s-o descopere din nou.","also":["soluții provizorii","workaround","ocolire"]},{"id":"knownerror","g":"run","word":"Eroare cunoscută","text":"O problemă a cărei cauză e înțeleasă și care are o soluție provizorie, dar nu e încă reparată. 🧩 Erori cunoscute le listează, ca toată lumea să folosească soluția provizorie în loc să sape din nou.","also":["erori cunoscute","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Instrucțiuni pas cu pas pentru a rezolva un tip cunoscut de problemă, ca să se facă la fel, repede, de fiecare dată. După un incident mare, echipa poate propune unul pentru care să dai OK.","also":["runbookuri","procedură","instrucțiuni de operare"]},{"id":"ci","g":"run","word":"Element de configurare","text":"Un lucru de care depinde serviciul tău, de exemplu un server, un domeniu, un certificat, o cheie sau un furnizor. 🗂️ Elemente de configurare le listează pe fiecare serviciu, ca să vezi ce afectează un incident și ce trebuie reînnoit sau salvat într-un backup.","also":["elemente de configurare"]},{"id":"expiry","g":"run","word":"Dată de expirare","text":"AI-gile urmărește date precum momentul în care expiră un certificat sau un domeniu. Cu 30 de zile înainte face un singur card pentru reînnoire, ca să nu se oprească nimic din senin.","also":["date de expirare","expirare","urmărirea expirării"]},{"id":"backup","g":"run","word":"Backup","text":"O copie salvată mai devreme a datelor tale, la care să revii dacă se pierde sau se strică ceva. AI-gile face zilnic un backup al panourilor tale.","also":["backupuri","copie de rezervă","copii de rezervă"]},{"id":"restore","g":"run","word":"Restaurare","text":"Aducerea datelor înapoi dintr-un backup. Un backup contează cu adevărat doar când știi că poate fi restaurat, așa că merită încercat din când în când.","also":["restaurat","restaurează","restore"]},{"id":"svcreview","g":"run","word":"Revizuirea serviciului","text":"O privire înapoi la o lună dintr-un serviciu: incidente deschise și rezolvate, cât de repede au primit oamenii răspuns, disponibilitate și tokeni folosiți. Revizuirea lunară arată asta pentru fiecare serviciu.","also":["revizuiri ale serviciului","revizuire lunară","revizuiri lunare"]},{"id":"accessreview","g":"run","word":"Revizuirea accesului","text":"Verifici la fiecare 90 de zile cine mai poate intra: link-uri de partajare, rolurile prietenilor și secretele păstrate. Pe fiecare îl păstrezi sau îl elimini, ca accesul vechi să nu rămână uitat.","also":["revizuiri ale accesului"]},{"id":"improvements","g":"run","word":"Lista de îmbunătățiri","text":"Tot ce a hotărât echipa să facă mai bine, într-un singur loc: sugestii din retro, acțiuni din revizii și reparații de probleme, fiecare cu statusul ei. O găsești la 📈 Îmbunătățiri.","also":["liste de îmbunătățiri","îmbunătățiri"]},{"id":"tokencap","g":"run","word":"Plafon de tokeni","text":"O limită lunară pentru tokenii pe care îi pot folosi agenții unui serviciu. La 80% primești un avertisment; la 100% munca lor din fundal așteaptă până luna viitoare sau până ridici plafonul.","also":["plafoane de tokeni","plafon lunar de tokeni"]},{"id":"backlog","g":"team","word":"Backlog","text":"Idei și muncă încă neplanificate. Nimic de acolo nu se lucrează până nu trece în De făcut."},{"id":"sprint","g":"team","word":"Sprint","text":"O perioadă scurtă de muncă (adesea o săptămână sau două) cu un set convenit de carduri de terminat.","also":["sprinturi","sprinturile","sprintul","sprintului","sprinturilor"]},{"id":"standup","g":"team","word":"Stand-up","text":"Un check-in rapid: ce a făcut fiecare membru al echipei, ce face în continuare și ce îl oprește.","also":["standup","stand-up-uri","stand-up-ul","stand-upuri","stand-upurile"]},{"id":"kanban","g":"team","word":"Kanban","text":"Un board cu coloane (De făcut, În lucru, Gata) în care cardurile merg de la stânga la dreapta pe măsură ce se lucrează."},{"id":"wip","g":"team","word":"Limită WIP","text":"Work in progress: cel mult câte carduri să țină o coloană, ca echipa să termine lucrurile înainte să înceapă altele.","also":["WIP"]},{"id":"dod","g":"team","word":"Definiția pentru Terminat","text":"Lista scurtă a echipei despre ce înseamnă „gata”, de exemplu testat și explicat, înainte ca un card să ajungă la tine. Geamăna ei, Definiția pentru Gata de start, spune când un card e destul de clar ca să fie început.","also":["Definition of Done","DoD","Definiția pentru Gata de start","Definition of Ready"]},{"id":"testpile","g":"team","word":"Grămada de teste","text":"Cardurile terminate care așteaptă să le încerci, unul după altul. Acceptă unul sau trimite-l înapoi cu o notă, și vine următorul.","also":["grămezi de teste","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"O privire înapoi la felul în care lucrează echipa, ca să cădeți de acord asupra unui lucru de făcut mai bine. În AI-gile, un retro propune o schimbare în felul de lucru al echipei, iar tu spui Dă-i drumul sau Încă nu.","also":["retrospectivă","retrospective"]},{"id":"peerreview","g":"team","word":"Revizuire de către colegi","text":"O a doua pereche de ochi: un alt AI verifică munca fiecărui card înainte să ajungă la tine, așa că trec mai puține greșeli.","also":["peer review","code review","revizuire de cod"]},{"id":"swarm","g":"team","word":"Roi","text":"Toată lumea la treabă: fiecare echipă lasă restul muncii ca să ajute la un singur proiect urgent până se rezolvă. Celelalte proiecte așteaptă între timp.","also":["roiul","swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Cel care ține munca în mișcare: observă cardurile blocate, împinge echipele de la spate și îți amintește ce așteaptă. În AI-gile, Lead Scrum Master face asta în toate proiectele.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Un AI care lucrează singur la o sarcină: citește codul, face modificări, rulează verificări și raportează.","also":["agenți","agentul","agentului"]},{"id":"token","g":"team","word":"Token","text":"Unitatea în care se numără utilizarea AI: aproximativ câteva litere de text citit sau scris. Mai puțini tokeni, mai mult rămas din plan.","also":["tokeni","tokenii","tokenilor"]},{"id":"hook","g":"team","word":"Hook","text":"O mică comandă care rulează singură la un moment stabilit, de ex. când pornește o sesiune AI, ca echipa să audă comentariile tale.","also":["hook-uri","hook-ul","hook-urile"]}]}};
